static size_t env_size(const char*n,size_t d){const char*s=getenv(n);return s&&*s?(size_t)strtoull(s,0,10):d;}
static const char*env_string(const char*n,const char*d){const char*s=getenv(n);return s&&*s?s:d;}
static uint64_t checksum16(const uint16_t*x,size_t n){uint64_t h=UINT64_C(1469598103934665603);for(size_t i=0;i<n;i++){h^=x[i];h*=UINT64_C(1099511628211);}return h;}
static uint64_t checksum_front(const uint16_t*c,const uint8_t*s,size_t n){uint64_t h=checksum16(c,n);for(size_t i=0;i<n;i++){h^=s[i];h*=UINT64_C(1099511628211);}return h;}
static const char*table_hash(const frodo_sampler_params*p){return p->id==FRODO_PARAM_640?"2b95ba3ee428d74cac5c2f9eb44a34790dc111b6abdf8276c82e22c53219edcd":p->id==FRODO_PARAM_976?"f03c0a76dff335db1a83eca315c624efa2158c4ff82376e51bfffde2068ea94c":"63594c67d3b8e2ec16892f94ad746d3c1cf88245999d8681cb19dcb96165267e";}
typedef struct{const frodo_sampler_params*p;const char*scope,*impl,*variant,*backend,*frontend,*order,*stream;const char*mode;size_t n,process,rep,accepted,words;uint64_t seed,cycles,checksum,replay;double attempts,rejections,logical,physical;int attempts_na,status,materialized;} row;
static void print_num(double x){printf("%.6f",x);}
static void emit(const row*r){printf("Frodo,%s,%u,%s,%s,%s,%s,%s,%s,%s,false,true,%s,%s,%zu,%zu,%ld,%zu,%s,%" PRIu64 ",%s,%" PRIu64 ",",r->p->name,r->p->sda_q,table_hash(r->p),r->scope,r->impl,r->variant,r->backend,r->frontend,r->mode,r->materialized?"true":"false",BENCH_TIMER_KIND,r->n,r->process,(long)getpid(),r->rep,r->order,r->seed,r->stream,r->cycles);print_num((double)r->cycles/r->n);putchar(',');if(r->attempts_na)printf("na,na,na");else{print_num((double)r->cycles/(r->attempts*r->n));putchar(',');print_num(r->attempts);putchar(',');print_num(r->rejections);}printf(",%zu,",r->accepted);if(r->words==(size_t)-1)printf("na,");else printf("%zu,",r->words);if(r->logical<0)printf("na");else print_num(r->logical);putchar(',');if(r->physical<0)printf("na");else print_num(r->physical);printf(",%" PRIu64 ",%" PRIu64 ",%s,%s,%s,%s,%s\n",r->checksum,r->replay,r->status?"error":"ok",FRODO_COMPILER_ID,FRODO_COMPILER_VERSION,FRODO_COMPILER_FLAGS,FRODO_GIT_COMMIT);}
static const char*position(int first,int which){return which==first?"first":"second";}
static void run_full(const frodo_sampler_params*p,const uint16_t*w,size_t wc,uint16_t*out,uint16_t*replay,size_t n,size_t proc,size_t rep,uint64_t seed,const char*mode,int emit_rows){int first=(rep&1)?1:0;for(int step=0;step<2;step++){int which=step==0?first:1-first;uint64_t a=bench_timer_start();int rc=which?frodo_sda_word_sample_n(out,n,w,wc,p->sda_table,0):frodo_original_sample_n_from_words(out,w,n,p->original_table);uint64_t b=bench_timer_stop();uint64_t ck=checksum16(out,n),rck;size_t attempts=n,rejections=0,words=n;if(which){sdat_stats st={0};int rr=frodo_sda_word_sample_n(replay,n,w,wc,p->sda_table,&st);attempts=(size_t)st.attempts;rejections=(size_t)st.rejections;words=(size_t)(st.random_bytes/2);rck=checksum16(replay,n);if(rr||ck!=rck)rc=-8;}else{int rr=frodo_original_sample_n_from_words(replay,w,n,p->original_table);rck=checksum16(replay,n);if(rr||ck!=rck)rc=-8;}if(emit_rows){row x={p,"full-sampler-core",which?"sda-word-reference":"original-reference",which?"branchless-map-before-accept":"official-cdt-reference","reference",which?"word-oriented":"original-word",position(first,which),WORD_STREAM,mode,n,proc,rep,n,words,seed,b-a,ck,rck,(double)attempts/n,(double)rejections/n,which?((double)(p->sda_candidate_bits*attempts+n)/n):16.0,which?((double)words*16/n):16.0,0,rc,0};emit(&x);}}}
static void run_front_pair(const frodo_sampler_params*p,const uint16_t*w,size_t wc,uint16_t*c,uint8_t*s,size_t n,size_t proc,size_t rep,uint64_t seed,const char*mode){int first=(rep&1)?1:0;for(int step=0;step<2;step++){int which=step==0?first:1-first;uint64_t a=bench_timer_start();size_t used=which?frodo_sda_materialize_words(c,s,n,w,wc,p->sda_table):frodo_original_materialize_words(c,s,n,w,wc);uint64_t b=bench_timer_stop(),ck=checksum_front(c,s,n);size_t attempts=which?used:n;row x={p,"standalone-materialized-input-frontend",which?"sda-frontend-reference":"original-frontend-reference","na","reference",which?"word-oriented":"original-word",position(first,which),WORD_STREAM,mode,n,proc,rep,n,used,seed,b-a,ck,ck,(double)attempts/n,(double)(attempts-n)/n,which?((double)(p->sda_candidate_bits*attempts+n)/n):16.0,(double)used*16/n,0,!used,1};emit(&x);}}
static void run_map_pair(const frodo_sampler_params*p,const uint16_t*oc,const uint8_t*os,const uint16_t*sc,const uint8_t*ss,uint16_t*out,size_t n,size_t proc,size_t rep,uint64_t seed,const char*mode){int first=(rep&1)?1:0;for(int step=0;step<2;step++){int which=step==0?first:1-first;const uint16_t*c=which?sc:oc;const uint8_t*s=which?ss:os;uint64_t a=bench_timer_start();for(size_t i=0;i<n;i++)out[i]=frodo_apply_sign(which?frodo_lookup_magnitude_scalar(c[i],p->sda_table):frodo_original_lookup_magnitude(c[i],p->original_table),s[i]);uint64_t b=bench_timer_stop(),ck=checksum16(out,n);row x={p,"standalone-cdt-mapping",which?"sda-mapping-reference":"original-mapping-reference","na","reference","materialized",position(first,which),WORD_STREAM,mode,n,proc,rep,n,(size_t)-1,seed,b-a,ck,ck,0,0,-1,-1,1,0,1};emit(&x);}}
static void run_diagnostic(const frodo_sampler_params*p,const uint16_t*w,size_t wc,uint16_t*out,uint16_t*replay,size_t n,size_t proc,size_t rep,uint64_t seed,const char*mode){int first=(rep&1)?1:0;for(int step=0;step<2;step++){int which=step==0?first:1-first;uint64_t a=bench_timer_start();int rc=which?frodo_sda_word_sample_n_accept_before_map(out,n,w,wc,p->sda_table):frodo_sda_word_sample_n(out,n,w,wc,p->sda_table,0);uint64_t b=bench_timer_stop();sdat_stats st={0};int rr=frodo_sda_word_sample_n(replay,n,w,wc,p->sda_table,&st);uint64_t ck=checksum16(out,n),rck=checksum16(replay,n);if(rr||ck!=rck)rc=-8;row x={p,"diagnostic-full-sampler",which?"sda-diagnostic-accept-before-map":"sda-diagnostic-map-before-accept-baseline",which?"accept-before-map":"branchless-map-before-accept","reference","word-oriented",position(first,which),WORD_STREAM,mode,n,proc,rep,n,(size_t)(st.random_bytes/2),seed,b-a,ck,rck,(double)st.attempts/n,(double)st.rejections/n,(double)(p->sda_candidate_bits*st.attempts+n)/n,(double)st.random_bytes*8/n,0,rc,0};emit(&x);}}
static void run_packed(const frodo_sampler_params*p,const uint8_t*buf,size_t len,uint16_t*out,uint16_t*replay,size_t n,size_t proc,size_t rep,uint64_t seed,const char*mode,int emit_rows){uint64_t a=bench_timer_start();sdat_bitreader_fast br;sdat_bitreader_fast_init(&br,buf,len);int rc=frodo_sda_sample_n_fast(out,n,&br,p->sda_table,0);uint64_t b=bench_timer_stop();sdat_stats st={0};sdat_bitreader_fast rb;sdat_bitreader_fast_init(&rb,buf,len);int rr=frodo_sda_sample_n_fast(replay,n,&rb,p->sda_table,&st);uint64_t ck=checksum16(out,n),rck=checksum16(replay,n);if(rr||ck!=rck)rc=-8;if(emit_rows){row x={p,"packed-bit-full-sampler","sda-packed-reference","na","reference","packed-bit","only",PACKED_STREAM,mode,n,proc,rep,n,(size_t)-1,seed,b-a,ck,rck,(double)st.attempts/n,(double)st.rejections/n,(double)st.random_bits/n,(double)st.random_bytes*8/n,0,rc,0};emit(&x);}}
static void run_optional_avx2(const frodo_sampler_params*p,const uint8_t*buf,size_t len,uint16_t*out,uint16_t*replay,size_t n,size_t proc,size_t rep,uint64_t seed,const char*mode,int emit_rows){if(!frodo_backend_available(FRODO_BACKEND_AVX2))return;sdat_bitreader_fast br;sdat_bitreader_fast_init(&br,buf,len);uint64_t a=bench_timer_start();int rc=frodo_sda_sample_n_fast_avx2(out,n,&br,p->sda_table,0);uint64_t b=bench_timer_stop();sdat_stats st={0};sdat_bitreader_fast rb;sdat_bitreader_fast_init(&rb,buf,len);int rr=frodo_sda_sample_n_fast(replay,n,&rb,p->sda_table,&st);uint64_t ck=checksum16(out,n),rck=checksum16(replay,n);if(rr||ck!=rck)rc=-8;if(emit_rows){row x={p,"optional-avx2-full-sampler","sda-packed-avx2","na","avx2","packed-bit","only",PACKED_STREAM,mode,n,proc,rep,n,(size_t)-1,seed,b-a,ck,rck,(double)st.attempts/n,(double)st.rejections/n,(double)st.random_bits/n,(double)st.random_bytes*8/n,0,rc,0};emit(&x);}}
static void run_case(const frodo_sampler_params*p,const char*scope,size_t n,size_t proc,size_t rep,const char*mode,int emit_rows){size_t wc=n*4+4096,len=n*8+4096;uint16_t*w=malloc(wc*sizeof*w),*out=malloc(n*sizeof*out),*replay=malloc(n*sizeof*replay),*oc=malloc(n*sizeof*oc),*sc=malloc(n*sizeof*sc);uint8_t*buf=malloc(len),*os=malloc(n),*ss=malloc(n);if(!w||!out||!replay||!oc||!sc||!buf||!os||!ss)exit(2);uint64_t wseed=frodo_benchmark_seed((unsigned)p->id,proc,rep,1),pseed=frodo_benchmark_seed((unsigned)p->id,proc,rep,2);frodo_benchmark_fill_words(w,wc,wseed);frodo_benchmark_fill_bytes(buf,len,pseed);if(!strcmp(scope,"full"))run_full(p,w,wc,out,replay,n,proc,rep,wseed,mode,emit_rows);else if(!strcmp(scope,"packed"))run_packed(p,buf,len,out,replay,n,proc,rep,pseed,mode,emit_rows);else if(!strcmp(scope,"avx2"))run_optional_avx2(p,buf,len,out,replay,n,proc,rep,pseed,mode,emit_rows);else if(!strcmp(scope,"micro")){if(!frodo_original_materialize_words(oc,os,n,w,wc)||!frodo_sda_materialize_words(sc,ss,n,w,wc,p->sda_table))exit(3);if(emit_rows){unsigned rotation=(unsigned)((rep+(size_t)p->id)%3);for(unsigned step=0;step<3;step++){switch((step+rotation)%3){case 0:run_front_pair(p,w,wc,oc,os,n,proc,rep,wseed,mode);break;case 1:run_map_pair(p,oc,os,sc,ss,out,n,proc,rep,wseed,mode);break;default:run_diagnostic(p,w,wc,out,replay,n,proc,rep,wseed,mode);break;}}}else{(void)frodo_sda_word_sample_n(out,n,w,wc,p->sda_table,0);(void)frodo_sda_word_sample_n_accept_before_map(replay,n,w,wc,p->sda_table);}}else exit(4);free(w);free(out);free(replay);free(oc);free(sc);free(buf);free(os);free(ss);}
int main(void){const char*scope=env_string("FRODO_BENCH_SCOPE","full"),*mode=env_string("FRODO_BENCH_MODE","equal-size");size_t reps=env_size("FRODO_BENCH_REPETITIONS",31),warm=env_size("FRODO_BENCH_WARMUP",5),count=env_size("FRODO_BENCH_SAMPLE_COUNT",1048576),proc=env_size("FRODO_BENCH_PROCESS_INDEX",0);if(strcmp(scope,"full")&&strcmp(scope,"micro")&&strcmp(scope,"packed")&&strcmp(scope,"avx2")){fprintf(stderr,"invalid FRODO_BENCH_SCOPE\n");return 2;}if(!strcmp(scope,"avx2")&&!frodo_backend_available(FRODO_BACKEND_AVX2)){fprintf(stderr,"AVX2 scope requested but AVX2 is unavailable\n");return 5;}puts(header);for(size_t w=0;w<warm;w++){const frodo_sampler_params*p=frodo_get_sampler_params((frodo_param_id)(w%3));run_case(p,scope,!strcmp(mode,"native-batch")?p->native_sample_count:count,proc,w,mode,0);}for(size_t rep=0;rep<reps;rep++)for(unsigned step=0;step<3;step++){const frodo_sampler_params*p=frodo_get_sampler_params((frodo_param_id)((step+rep)%3));run_case(p,scope,!strcmp(mode,"native-batch")?p->native_sample_count:count,proc,rep,mode,1);}return 0;}
